// Using the gadgets with the mouse and the keyboard. The window of the program tells what happened, and what belongs to
// the gadgets is taken from that: the program gets events for it instead. What belongs to a canvas stays with the
// program, with positions inside of the canvas.

#include "graphics_internal.hpp"

#include "gui_internal.hpp"

extern "C" {
void bb_minimize_window(int32_t handle);
void bb_maximize_window(int32_t handle);
void bb_restore_window(int32_t handle);
}

namespace bb::gui {
	bool (*modal_handler)(void const* event) = nullptr;

	namespace {
		enum part {
			PART_NONE,
			PART_GADGET,
			PART_TITLE,
			PART_CLOSE,
			PART_MAX,
			PART_MIN,
			PART_MENUBAR,
			PART_EDGE,
			PART_MINIMIZED,
			PART_BODY,
		};

		struct target {
			int window = 0, handle = 0, part = PART_NONE;
			int ax = 0, ay = 0; // Where the gadget is.
			int edges = 0;
			int index = -1; // Which menu of the bar.
		};

		enum drag_kind {
			D_NONE,
			D_WINDOW,
			D_RESIZE,
			D_SCROLL,
			D_HSCROLL,
			D_SLIDER,
			D_SELECT,
		};

		struct drag_state {
			int kind = D_NONE, handle = 0;
			int ox = 0, oy = 0; // Where the grab was.
			int edges = 0;
			int x = 0, y = 0, w = 0, h = 0; // The window when it started.
			int grab = 0;
			int vertical = 1;
		};

		drag_state drag;
		int        mouse_x = 0, mouse_y = 0;
		bool       swallow = false; // The press was used up by closing something, so the release is too.
		int        last_char = 0;

		enum bar_part { BP_NONE, BP_DEC, BP_INC, BP_PAGE_DEC, BP_PAGE_INC, BP_THUMB };

		bool inside(int x, int y, int rx, int ry, int rw, int rh)
		{
			return (x >= rx) && (y >= ry) && (x < rx + rw) && (y < ry + rh);
		}

		// Says what a position along a scroll bar is on.
		int bar_hit(int along, int position, int visible, int total, int length, int* grab)
		{
			if (along < 0 || along >= length) {
				return BP_NONE;
			}
			if (along < bar_width) {
				return BP_DEC;
			}
			if (along >= length - bar_width) {
				return BP_INC;
			}
			int start, size;
			scroll_thumb(position, visible, total, length, &start, &size);
			if (along < start) {
				return BP_PAGE_DEC;
			}
			if (along >= start + size) {
				return BP_PAGE_INC;
			}
			*grab = along - start;
			return BP_THUMB;
		}

		int clampi(int v, int lo, int hi)
		{
			return v < lo ? lo : (v > hi ? hi : v);
		}

		int& scroll_of(gadget& g)
		{
			return g.kind == K_TEXTAREA ? g.scroll_y : g.scroll;
		}

		////////////////////////////////////////////////////////////////////
		// Finding what is under the mouse
		////////////////////////////////////////////////////////////////////
		int pick_gadget(int group, int px, int py)
		{
			gadget* parent = gadget_of(group);
			for (int k = int(parent ? parent->kids.size : 0) - 1; k >= 0; k--) {
				int     handle = parent->kids[uint32_t(k)];
				gadget* kid    = gadget_of(handle);
				if (!kid || !kid->visible || !inside(px, py, kid->x, kid->y, kid->w, kid->h)) {
					continue;
				}
				if ((kid->kind == K_PANEL) || (kid->kind == K_TABBER) || (kid->kind == K_CANVAS)) {
					int cx, cy, cw, ch;
					client_rect(handle, &cx, &cy, &cw, &ch);
					if (inside(px - kid->x, py - kid->y, cx, cy, cw, ch)) {
						if (int deeper = pick_gadget(handle, px - kid->x - cx, py - kid->y - cy)) {
							return deeper;
						}
					}
				}
				return handle;
			}
			return 0;
		}

		target pick(int x, int y)
		{
			target t;
			gadget* desk = gadget_of(desktop_handle());
			for (int k = int(desk ? desk->kids.size : 0) - 1; k >= 0; k--) {
				int     handle = desk->kids[uint32_t(k)];
				gadget* w      = gadget_of(handle);
				if (!w || !w->visible) {
					continue;
				}
				if (w->minimized) {
					int mx, my, mw, mh;
					minimized_rect(handle, &mx, &my, &mw, &mh);
					if (inside(x, y, mx, my, mw, mh)) {
						t.window = handle;
						t.part   = PART_MINIMIZED;
						return t;
					}
					continue;
				}
				if (!inside(x, y, w->x, w->y, w->w, w->h)) {
					continue;
				}
				t.window  = handle;
				int rx    = x - w->x, ry = y - w->y;
				int cx, cy, cw, ch;
				client_rect(handle, &cx, &cy, &cw, &ch);
				if (inside(rx, ry, cx, cy, cw, ch)) {
					if (int hit = pick_gadget(handle, rx - cx, ry - cy)) {
						t.handle = hit;
						t.part   = PART_GADGET;
						absolute_position(hit, &t.ax, &t.ay);
						return t;
					}
					t.part = PART_BODY;
					return t;
				}
				// Around the client area.
				int frame = (w->style & 1) ? ((w->style & 2) ? frame_width : 3) : 1;
				if ((w->style & 2) && !w->maximized) {
					int e = 0;
					int corner = 16;
					if (rx < frame) e |= 1;
					if (rx >= w->w - frame) e |= 2;
					if (ry < frame) e |= 4;
					if (ry >= w->h - frame) e |= 8;
					if (!e) {
						if ((ry < corner) && (rx < frame + 2)) e |= 1 | 4;
					}
					if (e) {
						t.part  = PART_EDGE;
						t.edges = e;
						// Near the corner of a side, it is the corner.
						if ((e & 1) && (ry < corner)) t.edges |= 4;
						if ((e & 1) && (ry >= w->h - corner)) t.edges |= 8;
						if ((e & 2) && (ry < corner)) t.edges |= 4;
						if ((e & 2) && (ry >= w->h - corner)) t.edges |= 8;
						if ((e & 4) && (rx < corner)) t.edges |= 1;
						if ((e & 4) && (rx >= w->w - corner)) t.edges |= 2;
						if ((e & 8) && (rx < corner)) t.edges |= 1;
						if ((e & 8) && (rx >= w->w - corner)) t.edges |= 2;
						return t;
					}
				}
				if (w->style & 1) {
					int close_x, max_x, min_x, by;
					int buttons = window_buttons(*w, &close_x, &max_x, &min_x, &by);
					int bw = title_box_width(*w), bh = title_box_height(*w);
					if (inside(rx, ry, close_x, by, bw, bh)) {
						t.part = PART_CLOSE;
						return t;
					}
					if ((buttons == 3) && inside(rx, ry, max_x, by, bw, bh)) {
						t.part = PART_MAX;
						return t;
					}
					if ((buttons == 3) && inside(rx, ry, min_x, by, bw, bh)) {
						t.part = PART_MIN;
						return t;
					}
					if (inside(rx, ry, frame, frame, w->w - 2 * frame, title_bar_height(*w))) {
						t.part = PART_TITLE;
						return t;
					}
				}
				if (w->style & 4) {
					menu* root = menu_of(w->menu);
					for (int i = 0; root && (i < int(root->kids.size)); i++) {
						int bx, by, bw, bh;
						menu_bar_rect(handle, i, &bx, &by, &bw, &bh);
						if (inside(rx, ry, bx, by, bw, bh)) {
							t.part  = PART_MENUBAR;
							t.index = i;
							return t;
						}
					}
				}
				t.part = PART_BODY;
				return t;
			}
			return t;
		}

		////////////////////////////////////////////////////////////////////
		// Menus
		////////////////////////////////////////////////////////////////////
		void close_menus()
		{
			if (ui.menu_window || ui.menu_path.size) {
				ui.menu_window = 0;
				ui.menu_path.clear();
				dirty();
			}
		}

		void fire_menu(int window, int handle)
		{
			menu* m = menu_of(handle);
			if (!m || !m->enabled) {
				return;
			}
			post_to(event_menu_action, window, m->tag);
			close_menus();
		}

		// What is in a menu at a position, or -1.
		int menu_row_at(int window, int level, int x, int y)
		{
			gadget* g = gadget_of(window);
			menu*   m = menu_of(ui.menu_path[uint32_t(level)]);
			int     px, py, pw, ph;
			menu_popup_rect(window, level, &px, &py, &pw, &ph);
			if (!g || !m || !inside(x - g->x, y - g->y, px, py, pw, ph)) {
				return -1;
			}
			int row = (y - g->y - py - 2) / menu_row_height();
			return (row >= 0) && (row < int(m->kids.size)) ? row : -1;
		}

		// Press or move over menus that are open. Says whether the mouse is in them.
		bool menu_mouse(int x, int y, bool press)
		{
			int window = ui.menu_window;
			gadget* g  = gadget_of(window);
			if (!g) {
				return false;
			}
			for (int level = int(ui.menu_path.size) - 1; level >= 0; level--) {
				int row = menu_row_at(window, level, x, y);
				if (row < 0) {
					continue;
				}
				menu* m    = menu_of(ui.menu_path[uint32_t(level)]);
				int   item = m->kids[uint32_t(row)];
				menu* kid  = menu_of(item);
				if (!kid || !kid->text || !*kid->text) {
					return true;
				}
				if (kid->kids.size) {
					if ((ui.menu_path.size != uint32_t(level + 2)) || (ui.menu_path[uint32_t(level + 1)] != item)) {
						ui.menu_path.size = uint32_t(level + 1);
						ui.menu_path.push(item);
						dirty();
					}
				} else if (press) {
					fire_menu(window, item);
				} else if (ui.menu_path.size != uint32_t(level + 1)) {
					ui.menu_path.size = uint32_t(level + 1);
					dirty();
				}
				return true;
			}
			return false;
		}

		void open_menu_bar(int window, int index)
		{
			gadget* g    = gadget_of(window);
			menu*   root = g ? menu_of(g->menu) : nullptr;
			if (!root || (index < 0) || (index >= int(root->kids.size))) {
				return;
			}
			int   item = root->kids[uint32_t(index)];
			menu* m    = menu_of(item);
			if (m && m->kids.size) {
				ui.menu_window = window;
				ui.menu_path.clear();
				ui.menu_path.push(item);
				dirty();
			} else {
				fire_menu(window, item);
			}
		}

		////////////////////////////////////////////////////////////////////
		// Text
		////////////////////////////////////////////////////////////////////
		int text_len(gadget const& g)
		{
			return g.text ? int(strlen(g.text)) : 0;
		}

		// Which character a position in a text field or text area is at.
		int caret_at(gadget& g, int lx, int ly)
		{
			int size = font_size(g);
			if (g.kind == K_TEXTFIELD) {
				int c = (lx - 3 + g.scroll_x + size / 2) / size;
				return clampi(c, 0, text_len(g));
			}
			buffer<visual_line> lines;
			build_lines(g, lines);
			int row = g.scroll_y + (ly - 2) / row_height(g);
			row     = clampi(row, 0, int(lines.size) - 1);
			int shown_x = (g.style & 1) ? 0 : g.scroll_x;
			int col     = (lx - 2 + shown_x + size / 2) / size;
			col         = clampi(col, 0, lines[uint32_t(row)].length);
			int result  = lines[uint32_t(row)].start + col;
			// The end of a wrapped line that goes on is the start of the next.
			if ((g.style & 1) && (col == lines[uint32_t(row)].length) && (row + 1 < int(lines.size))
			    && (lines[uint32_t(row + 1)].start == result) && (col > 0)) {
				result--;
			}
			lines.release();
			return result;
		}

		void selection_changed(int handle, gadget& g)
		{
			if ((g.kind == K_TEXTAREA) && !g.locked) {
				post_action(handle, 0);
			}
		}

		// Puts text in place of what is selected.
		void replace_selection(int handle, gadget& g, const char* insert, int key)
		{
			int lo = g.caret < g.anchor ? g.caret : g.anchor, hi = g.caret < g.anchor ? g.anchor : g.caret;
			int before = text_len(g);
			if (g.kind == K_TEXTFIELD) {
				char* clean = copy_string(insert);
				for (char* p = clean; *p; p++) {
					if ((*p == '\r') || (*p == '\n')) {
						*p = 0;
						break;
					}
				}
				int   add  = int(strlen(clean));
				char* body = static_cast<char*>(malloc(size_t(before - (hi - lo) + add) + 1));
				memcpy(body, g.text, size_t(lo));
				memcpy(body + lo, clean, size_t(add));
				memcpy(body + lo + add, g.text + hi, size_t(before - hi));
				body[before - (hi - lo) + add] = 0;
				free(g.text);
				g.text   = body;
				g.caret  = g.anchor = lo + add;
				free(clean);
				caret_to_view(g);
				post_action(handle, key);
			} else {
				text_area_insert(g, lo, hi - lo, insert);
				int added = text_len(g) - before + (hi - lo);
				g.caret   = g.anchor = lo + added;
				caret_to_view(g);
				if (!g.locked) {
					post_action(handle, 1);
				}
			}
			dirty();
		}

		void move_caret(int handle, gadget& g, int to, bool extend)
		{
			to = clampi(to, 0, text_len(g));
			bool moved = (g.caret != to) || (!extend && (g.anchor != to));
			g.caret    = to;
			if (!extend) {
				g.anchor = to;
			}
			caret_to_view(g);
			if (moved) {
				selection_changed(handle, g);
			}
		}

		// The line that a character is on, and how far in it is.
		int visual_row(buffer<visual_line> const& lines, int pos, gadget const& g)
		{
			int row = 0;
			for (uint32_t i = 0; i < lines.size; i++) {
				if ((pos >= lines[i].start) && (pos <= lines[i].start + lines[i].length)) {
					row = int(i);
					if ((pos < lines[i].start + lines[i].length) || !(g.style & 1) || (i + 1 == lines.size) || (g.text[pos] == '\r')) {
						break;
					}
				}
			}
			return row;
		}

		bool edit_key(int handle, gadget& g, SDL_Scancode key, SDL_Keymod mods)
		{
			bool shift = (mods & SDL_KMOD_SHIFT) != 0, ctrl = (mods & SDL_KMOD_CTRL) != 0;
			int  n = text_len(g);
			int  lo = g.caret < g.anchor ? g.caret : g.anchor, hi = g.caret < g.anchor ? g.anchor : g.caret;
			bool area = g.kind == K_TEXTAREA;
			switch (key) {
			case SDL_SCANCODE_LEFT:
				if (!shift && (hi > lo)) {
					move_caret(handle, g, lo, false);
				} else {
					int to = g.caret - 1;
					if (ctrl) {
						while ((to > 0) && (g.text[to - 1] != ' ') && (g.text[to - 1] != '\r')) {
							to--;
						}
					}
					move_caret(handle, g, to, shift);
				}
				return true;
			case SDL_SCANCODE_RIGHT:
				if (!shift && (hi > lo)) {
					move_caret(handle, g, hi, false);
				} else {
					int to = g.caret + 1;
					if (ctrl) {
						while ((to < n) && (g.text[to] != ' ') && (g.text[to] != '\r')) {
							to++;
						}
					}
					move_caret(handle, g, to, shift);
				}
				return true;
			case SDL_SCANCODE_HOME:
			case SDL_SCANCODE_END: {
				bool home = key == SDL_SCANCODE_HOME;
				if (!area || ctrl) {
					move_caret(handle, g, home ? 0 : n, shift);
				} else {
					buffer<visual_line> lines;
					build_lines(g, lines);
					visual_line l = lines[uint32_t(visual_row(lines, g.caret, g))];
					lines.release();
					move_caret(handle, g, home ? l.start : l.start + l.length, shift);
				}
				return true;
			}
			case SDL_SCANCODE_UP:
			case SDL_SCANCODE_DOWN:
			case SDL_SCANCODE_PAGEUP:
			case SDL_SCANCODE_PAGEDOWN: {
				if (!area) {
					return key == SDL_SCANCODE_UP || key == SDL_SCANCODE_DOWN;
				}
				buffer<visual_line> lines;
				build_lines(g, lines);
				int row  = visual_row(lines, g.caret, g);
				int col  = g.caret - lines[uint32_t(row)].start;
				int step = (key == SDL_SCANCODE_UP || key == SDL_SCANCODE_DOWN) ? 1 : visible_rows(g);
				int to   = clampi(row + ((key == SDL_SCANCODE_UP || key == SDL_SCANCODE_PAGEUP) ? -step : step), 0, int(lines.size) - 1);
				int pos  = lines[uint32_t(to)].start + (col < lines[uint32_t(to)].length ? col : lines[uint32_t(to)].length);
				lines.release();
				move_caret(handle, g, pos, shift);
				return true;
			}
			case SDL_SCANCODE_BACKSPACE:
				if (hi == lo) {
					if (lo == 0) {
						return true;
					}
					g.anchor = lo - 1;
					g.caret  = lo;
				}
				last_char = 8;
				replace_selection(handle, g, "", 8);
				return true;
			case SDL_SCANCODE_DELETE:
				if (hi == lo) {
					if (lo >= n) {
						return true;
					}
					g.anchor = lo;
					g.caret  = lo + 1;
				}
				replace_selection(handle, g, "", last_char);
				return true;
			case SDL_SCANCODE_RETURN:
			case SDL_SCANCODE_KP_ENTER:
				if (area) {
					replace_selection(handle, g, "\r", 13);
				} else {
					post_action(handle, 13);
				}
				return true;
			case SDL_SCANCODE_TAB:
				if (area) {
					replace_selection(handle, g, "\t", 9);
					return true;
				}
				return false;
			case SDL_SCANCODE_A:
				if (ctrl) {
					g.anchor = 0;
					g.caret  = n;
					caret_to_view(g);
					selection_changed(handle, g);
					return true;
				}
				return false;
			case SDL_SCANCODE_C:
			case SDL_SCANCODE_X:
				if (ctrl) {
					if (hi > lo) {
						char* part = static_cast<char*>(malloc(size_t(hi - lo) + 1));
						memcpy(part, g.text + lo, size_t(hi - lo));
						part[hi - lo] = 0;
						for (char* p = part; *p; p++) {
							// Text areas keep line ends as Chr(13), and the clipboard has the ones of the system.
							if (*p == '\r') {
								*p = '\n';
							}
						}
						SDL_SetClipboardText(part);
						free(part);
						if (key == SDL_SCANCODE_X) {
							replace_selection(handle, g, "", last_char);
						}
					}
					return true;
				}
				return false;
			case SDL_SCANCODE_V:
				if (ctrl) {
					char* clip = SDL_GetClipboardText();
					if (clip && *clip) {
						replace_selection(handle, g, clip, last_char);
					}
					SDL_free(clip);
					return true;
				}
				return false;
			default:
				return false;
			}
		}

		////////////////////////////////////////////////////////////////////
		// Lists, trees and sliders with the keyboard
		////////////////////////////////////////////////////////////////////
		void trigger_button(int handle, gadget& g)
		{
			if (!g.enabled) {
				return;
			}
			if (g.style == 2) {
				g.state = g.state ? 0 : 1;
			} else if (g.style == 3) {
				gadget* parent = gadget_of(g.parent);
				for (uint32_t i = 0; parent && (i < parent->kids.size); i++) {
					gadget* sibling = gadget_of(parent->kids[i]);
					if (sibling && (sibling->kind == K_BUTTON) && (sibling->style == 3)) {
						sibling->state = 0;
					}
				}
				g.state = 1;
			}
			post_action(handle, ((g.style == 2) || (g.style == 3)) ? g.state : 0);
			dirty();
		}

		void slider_set(int handle, gadget& g, int value, bool post)
		{
			value = clampi(value, 0, slider_limit(g));
			if (value != g.state) {
				g.state = value;
				if (post) {
					post_action(handle, value);
				}
				dirty();
			}
		}

		void scroll_by(gadget& g, int amount)
		{
			scroll_of(g) += amount;
			clamp_scroll(g);
			dirty();
		}

		bool list_key(int handle, gadget& g, SDL_Scancode key)
		{
			int n = int(g.items.size);
			switch (g.kind) {
			case K_LISTBOX:
			case K_COMBOBOX:
			case K_TABBER: {
				int to = g.selected;
				bool tab = g.kind == K_TABBER;
				switch (key) {
				case SDL_SCANCODE_UP:
					if (tab) return false;
					to = g.selected - 1;
					break;
				case SDL_SCANCODE_DOWN:
					if (tab) return false;
					to = g.selected + 1;
					break;
				case SDL_SCANCODE_LEFT:
					if (!tab) return false;
					to = g.selected - 1;
					break;
				case SDL_SCANCODE_RIGHT:
					if (!tab) return false;
					to = g.selected + 1;
					break;
				case SDL_SCANCODE_PAGEUP:
					to = g.selected - visible_rows(g);
					break;
				case SDL_SCANCODE_PAGEDOWN:
					to = g.selected + visible_rows(g);
					break;
				case SDL_SCANCODE_HOME:
					to = 0;
					break;
				case SDL_SCANCODE_END:
					to = n - 1;
					break;
				case SDL_SCANCODE_RETURN:
				case SDL_SCANCODE_ESCAPE:
					if ((g.kind == K_COMBOBOX) && (ui.combo == handle)) {
						ui.combo = 0;
						dirty();
						return true;
					}
					return false;
				default:
					return false;
				}
				to = clampi(to, 0, n - 1);
				if ((n > 0) && (to != g.selected)) {
					select_item(handle, to, true);
					if (g.kind == K_COMBOBOX) {
						if (to < g.scroll) g.scroll = to;
						if (to >= g.scroll + 8) g.scroll = to - 7;
					}
				}
				return true;
			}
			case K_TREEVIEW: {
				buffer<tree_row> rows;
				build_tree_rows(g, rows);
				int at = -1;
				for (uint32_t i = 0; i < rows.size; i++) {
					if (rows[i].node == g.selected_node) {
						at = int(i);
					}
				}
				bool used = true;
				switch (key) {
				case SDL_SCANCODE_UP:
					if (at > 0) select_tree_node(rows[uint32_t(at - 1)].node, true);
					break;
				case SDL_SCANCODE_DOWN:
					if (at + 1 < int(rows.size)) select_tree_node(rows[uint32_t(at + 1)].node, true);
					break;
				case SDL_SCANCODE_RIGHT:
					if ((at >= 0) && node_of(rows[uint32_t(at)].node)->kids.size) expand_node(rows[uint32_t(at)].node, true);
					break;
				case SDL_SCANCODE_LEFT:
					if (at >= 0) {
						node* nd = node_of(rows[uint32_t(at)].node);
						if (nd->expanded) {
							expand_node(rows[uint32_t(at)].node, false);
						} else if (nd->parent && node_of(nd->parent)->parent) {
							select_tree_node(nd->parent, true);
						}
					}
					break;
				default:
					used = false;
					break;
				}
				rows.release();
				if (used) {
					// What is selected is seen.
					buffer<tree_row> again;
					build_tree_rows(g, again);
					for (uint32_t i = 0; i < again.size; i++) {
						if (again[i].node == g.selected_node) {
							if (int(i) < g.scroll) g.scroll = int(i);
							if (int(i) >= g.scroll + visible_rows(g)) g.scroll = int(i) - visible_rows(g) + 1;
						}
					}
					again.release();
					clamp_scroll(g);
					dirty();
				}
				return used;
			}
			case K_SLIDER: {
				bool horizontal = slider_horizontal(g);
				int  page = g.range_visible > 0 ? g.range_visible : 1;
				switch (key) {
				case SDL_SCANCODE_LEFT:
				case SDL_SCANCODE_UP:
					slider_set(handle, g, g.state - 1, true);
					return true;
				case SDL_SCANCODE_RIGHT:
				case SDL_SCANCODE_DOWN:
					slider_set(handle, g, g.state + 1, true);
					return true;
				case SDL_SCANCODE_PAGEUP:
					slider_set(handle, g, g.state - page, true);
					return true;
				case SDL_SCANCODE_PAGEDOWN:
					slider_set(handle, g, g.state + page, true);
					return true;
				case SDL_SCANCODE_HOME:
					slider_set(handle, g, 0, true);
					return true;
				case SDL_SCANCODE_END:
					slider_set(handle, g, slider_limit(g), true);
					return true;
				default:
					(void)horizontal;
					return false;
				}
			}
			default:
				return false;
			}
		}

		// Everything in a window that can be used with the keyboard, in the order of the tab key.
		void collect_focusable(int group, buffer<int>& out)
		{
			gadget* parent = gadget_of(group);
			for (uint32_t i = 0; parent && (i < parent->kids.size); i++) {
				gadget* kid = gadget_of(parent->kids[i]);
				if (!kid || !kid->visible) {
					continue;
				}
				switch (kid->kind) {
				case K_BUTTON:
				case K_TEXTFIELD:
				case K_TEXTAREA:
				case K_LISTBOX:
				case K_COMBOBOX:
				case K_TABBER:
				case K_TREEVIEW:
				case K_SLIDER:
				case K_CANVAS:
					if (kid->enabled) {
						out.push(parent->kids[i]);
					}
					break;
				default:
					break;
				}
				if ((kid->kind == K_PANEL) || (kid->kind == K_TABBER)) {
					collect_focusable(parent->kids[i], out);
				}
			}
		}

		void focus_next(bool backwards)
		{
			int window = active_window();
			if (!window) {
				return;
			}
			buffer<int> all;
			collect_focusable(window, all);
			if (all.size) {
				int at = -1;
				for (uint32_t i = 0; i < all.size; i++) {
					if (all[i] == ui.focus) {
						at = int(i);
					}
				}
				int n = int(all.size);
				at    = at < 0 ? (backwards ? n - 1 : 0) : ((at + (backwards ? n - 1 : 1)) % n);
				ui.focus = all[uint32_t(at)];
				gadget* f = gadget_of(ui.focus);
				if (f && ((f->kind == K_TEXTFIELD) || (f->kind == K_TEXTAREA)) && (f->text != nullptr)) {
					f->anchor = 0;
					f->caret  = text_len(*f);
				}
				dirty();
			}
			all.release();
		}

		// Finds the button that Return or Escape press.
		int default_button(int group, int style)
		{
			gadget* parent = gadget_of(group);
			for (uint32_t i = 0; parent && (i < parent->kids.size); i++) {
				gadget* kid = gadget_of(parent->kids[i]);
				if (!kid || !kid->visible) {
					continue;
				}
				if ((kid->kind == K_BUTTON) && (kid->style == style) && kid->enabled) {
					return parent->kids[i];
				}
				if ((kid->kind == K_PANEL) || (kid->kind == K_TABBER)) {
					if (int h = default_button(parent->kids[i], style)) {
						return h;
					}
				}
			}
			return 0;
		}

		////////////////////////////////////////////////////////////////////
		// The mouse
		////////////////////////////////////////////////////////////////////
		void set_hover(int hover)
		{
			if (hover == ui.hover) {
				return;
			}
			gadget* old     = gadget_of(ui.hover);
			gadget* fresh   = gadget_of(hover);
			bool    leaving = old && (old->kind == K_CANVAS), entering = fresh && (fresh->kind == K_CANVAS);
			int     previous = ui.hover;
			ui.hover        = hover;
			if (old && (old->kind == K_TOOLBAR)) {
				old->tool_hot = -1;
			}
			if (leaving && !ui.pressed) {
				post_to(event_mouse_leave, previous, 0, 0, 0, 0);
			}
			if (entering && !ui.pressed) {
				int ax, ay;
				absolute_position(hover, &ax, &ay);
				post_to(event_mouse_enter, hover, 0, mouse_x - ax, mouse_y - ay, 0);
			}
			dirty();
		}

		void resize_to(int handle, gadget& w, int x, int y)
		{
			int dx = x - drag.ox, dy = y - drag.oy;
			int nx = drag.x, ny = drag.y, nw = drag.w, nh = drag.h;
			int min_w = w.min_w > 100 ? w.min_w : 100, min_h = w.min_h > 40 ? w.min_h : 40;
			if (drag.edges & 1) {
				nw = drag.w - dx;
				if (nw < min_w) nw = min_w;
				nx = drag.x + drag.w - nw;
			}
			if (drag.edges & 2) {
				nw = drag.w + dx;
				if (nw < min_w) nw = min_w;
			}
			if (drag.edges & 4) {
				nh = drag.h - dy;
				if (nh < min_h) nh = min_h;
				ny = drag.y + drag.h - nh;
			}
			if (drag.edges & 8) {
				nh = drag.h + dy;
				if (nh < min_h) nh = min_h;
			}
			set_shape(handle, nx, ny, nw, nh);
			(void)w;
		}

		void on_motion(int x, int y)
		{
			mouse_x = x;
			mouse_y = y;
			switch (drag.kind) {
			case D_WINDOW: {
				gadget* w = gadget_of(drag.handle);
				if (w) {
					int ny = y - drag.oy;
					set_shape(drag.handle, x - drag.ox, ny < 0 ? 0 : ny, w->w, w->h);
				}
				return;
			}
			case D_RESIZE: {
				gadget* w = gadget_of(drag.handle);
				if (w) {
					resize_to(drag.handle, *w, x, y);
				}
				return;
			}
			case D_SCROLL: {
				gadget* g = gadget_of(drag.handle);
				if (g) {
					int ax, ay;
					absolute_position(drag.handle, &ax, &ay);
					int sx, sy, sw, sh;
					scroll_rect(*g, &sx, &sy, &sw, &sh);
					int along = y - (ay + sy) - drag.grab;
					int visible = visible_rows(*g), total = total_rows(*g);
					int start, size;
					scroll_thumb(scroll_of(*g), visible, total, sh, &start, &size);
					int track = sh - 2 * bar_width - size;
					if ((track > 0) && (total > visible)) {
						scroll_of(*g) = int(int64_t(along - bar_width) * (total - visible) / track);
						clamp_scroll(*g);
						dirty();
					}
				}
				return;
			}
			case D_HSCROLL: {
				gadget* g = gadget_of(drag.handle);
				if (g) {
					int ax, ay;
					absolute_position(drag.handle, &ax, &ay);
					int hx, hy, hw, hh;
					hscroll_rect(*g, &hx, &hy, &hw, &hh);
					int total = longest_line_width(*g);
					int start, size;
					scroll_thumb(g->scroll_x, hw, total, hw, &start, &size);
					int track = hw - 2 * bar_width - size;
					if ((track > 0) && (total > hw)) {
						g->scroll_x = int(int64_t(x - (ax + hx) - drag.grab - bar_width) * (total - hw) / track);
						clamp_scroll(*g);
						dirty();
					}
				}
				return;
			}
			case D_SLIDER: {
				gadget* g = gadget_of(drag.handle);
				if (g) {
					int  ax, ay;
					absolute_position(drag.handle, &ax, &ay);
					bool horizontal = slider_horizontal(*g);
					int  length = horizontal ? g->w : g->h;
					int  along  = (horizontal ? x - ax : y - ay) - drag.grab;
					int  visible = g->range_visible > 0 ? g->range_visible : 1, limit = slider_limit(*g);
					int  start, size;
					scroll_thumb(g->state, visible, limit + visible, length, &start, &size);
					int track = length - 2 * bar_width - size;
					if (track > 0) {
						slider_set(drag.handle, *g, int(int64_t(along - bar_width) * limit / track), true);
					}
				}
				return;
			}
			case D_SELECT: {
				gadget* g = gadget_of(drag.handle);
				if (g) {
					int ax, ay;
					absolute_position(drag.handle, &ax, &ay);
					int to = caret_at(*g, x - ax, y - ay);
					if (to != g->caret) {
						g->caret = to;
						caret_to_view(*g);
						selection_changed(drag.handle, *g);
					}
				}
				return;
			}
			default:
				break;
			}
			if (ui.menu_window) {
				if (menu_mouse(x, y, false)) {
					return;
				}
				// Moving along the bar changes which menu is open.
				target t = pick(x, y);
				if ((t.part == PART_MENUBAR) && (t.window == ui.menu_window)) {
					gadget* w    = gadget_of(t.window);
					menu*   root = w ? menu_of(w->menu) : nullptr;
					if (root && ((ui.menu_path.size == 0) || (ui.menu_path[0] != root->kids[uint32_t(t.index)]))) {
						open_menu_bar(t.window, t.index);
					}
				}
				return;
			}
			target t = ui.pressed ? target() : pick(x, y);
			int    hover = ui.pressed ? ui.hover : (t.part == PART_GADGET ? t.handle : 0);
			if (ui.pressed) {
				// While a button is held, what it is on is whether the mouse is still on it.
				gadget* p = gadget_of(ui.pressed);
				int     ax, ay;
				absolute_position(ui.pressed, &ax, &ay);
				if (p && (p->kind != K_CANVAS)) {
					int now = inside(x, y, ax, ay, p->w, p->h) && shown(ui.pressed) ? ui.pressed : 0;
					if (now != ui.hover) {
						ui.hover = now;
						dirty();
					}
				}
				hover = ui.hover;
			} else {
				if (ui.combo) {
					// An open list is over other things.
					gadget* c = gadget_of(ui.combo);
					int     ax, ay;
					absolute_position(ui.combo, &ax, &ay);
					int rows = c ? (int(c->items.size) < 8 ? int(c->items.size) : 8) : 0;
					if (c && inside(x, y, ax, ay + c->h, c->w, rows * row_height(*c) + 4)) {
						hover = ui.combo;
					}
				}
				set_hover(hover);
			}
			gadget* h = gadget_of(hover);
			if (h && (h->kind == K_TOOLBAR)) {
				int ax, ay;
				absolute_position(hover, &ax, &ay);
				int fresh = -1;
				icon_strip* strip = strip_of(h->strip);
				for (int i = 0; strip && (i < strip->count); i++) {
					int bx, by, bw, bh;
					tool_button_rect(*h, i, &bx, &by, &bw, &bh);
					if (inside(x - ax, y - ay, bx, by, bw, bh)) {
						fresh = tool_button_index(*h, i);
					}
				}
				if (fresh != h->tool_hot) {
					h->tool_hot = fresh;
					dirty();
				}
			}
		}

		void start_scroll_drag(int handle, int grab)
		{
			drag.kind   = D_SCROLL;
			drag.handle = handle;
			drag.grab   = grab;
		}

		// A press on the scroll bar of a list, text area or tree view.
		void bar_press(int handle, gadget& g, int ax, int ay, int x, int y)
		{
			int sx, sy, sw, sh;
			scroll_rect(g, &sx, &sy, &sw, &sh);
			int grab = 0;
			int part = bar_hit(y - ay - sy, scroll_of(g), visible_rows(g), total_rows(g), sh, &grab);
			switch (part) {
			case BP_DEC:
				scroll_by(g, -1);
				break;
			case BP_INC:
				scroll_by(g, 1);
				break;
			case BP_PAGE_DEC:
				scroll_by(g, -visible_rows(g));
				break;
			case BP_PAGE_INC:
				scroll_by(g, visible_rows(g));
				break;
			case BP_THUMB:
				start_scroll_drag(handle, grab);
				break;
			default:
				break;
			}
			(void)ax;
			(void)x;
		}

		bool on_hbar(gadget const& g, int lx, int ly)
		{
			int hx, hy, hw, hh;
			hscroll_rect(g, &hx, &hy, &hw, &hh);
			return has_hbar(g) && inside(lx, ly, hx, hy, hw, hh);
		}

		// A press on the bar along the bottom of a text area: arrows go four characters, the track a page.
		void hbar_press(int handle, gadget& g, int ax, int x)
		{
			int hx, hy, hw, hh;
			hscroll_rect(g, &hx, &hy, &hw, &hh);
			int grab = 0;
			int part = bar_hit(x - ax - hx, g.scroll_x, hw, longest_line_width(g), hw, &grab);
			int step = font_size(g) * 4;
			switch (part) {
			case BP_DEC:
				g.scroll_x -= step;
				break;
			case BP_INC:
				g.scroll_x += step;
				break;
			case BP_PAGE_DEC:
				g.scroll_x -= hw;
				break;
			case BP_PAGE_INC:
				g.scroll_x += hw;
				break;
			case BP_THUMB:
				drag.kind   = D_HSCROLL;
				drag.handle = handle;
				drag.grab   = grab;
				return;
			default:
				return;
			}
			clamp_scroll(g);
			dirty();
		}

		bool on_bar(gadget const& g, int lx, int ly)
		{
			int sx, sy, sw, sh;
			scroll_rect(g, &sx, &sy, &sw, &sh);
			bool shown_bar = (g.kind == K_TEXTAREA) || (total_rows(g) > visible_rows(g));
			return shown_bar && inside(lx, ly, sx, sy, sw, sh);
		}

		void press_gadget(int handle, gadget& g, int x, int y, int ax, int ay)
		{
			int lx = x - ax, ly = y - ay;
			if (!g.enabled) {
				return;
			}
			switch (g.kind) {
			case K_BUTTON:
				ui.pressed = handle;
				ui.hover   = handle;
				ui.focus   = handle;
				break;
			case K_TEXTFIELD:
			case K_TEXTAREA: {
				ui.focus = handle;
				if ((g.kind == K_TEXTAREA) && on_bar(g, lx, ly)) {
					bar_press(handle, g, ax, ay, x, y);
					break;
				}
				if ((g.kind == K_TEXTAREA) && on_hbar(g, lx, ly)) {
					hbar_press(handle, g, ax, x);
					break;
				}
				bool shift = (SDL_GetModState() & SDL_KMOD_SHIFT) != 0;
				int  to    = caret_at(g, lx, ly);
				g.caret    = to;
				if (!shift) {
					g.anchor = to;
				}
				drag.kind   = D_SELECT;
				drag.handle = handle;
				caret_to_view(g);
				selection_changed(handle, g);
				break;
			}
			case K_LISTBOX: {
				ui.focus = handle;
				if (on_bar(g, lx, ly)) {
					bar_press(handle, g, ax, ay, x, y);
					break;
				}
				int row = g.scroll + (ly - 2) / row_height(g);
				if ((ly >= 2) && (row >= 0) && (row < int(g.items.size))) {
					select_item(handle, row, true);
				}
				break;
			}
			case K_COMBOBOX:
				ui.focus = handle;
				ui.combo = ui.combo == handle ? 0 : handle;
				dirty();
				break;
			case K_TABBER:
				ui.focus = handle;
				for (int i = 0; i < int(g.items.size); i++) {
					int rx, ry, rw, rh;
					tab_rect(g, i, &rx, &ry, &rw, &rh);
					if (inside(lx, ly, rx, ry, rw, rh) && (i != g.selected)) {
						select_item(handle, i, true);
					}
				}
				break;
			case K_TREEVIEW: {
				ui.focus = handle;
				if (on_bar(g, lx, ly)) {
					bar_press(handle, g, ax, ay, x, y);
					break;
				}
				buffer<tree_row> rows;
				build_tree_rows(g, rows);
				int row = g.scroll + (ly - 2) / row_height(g);
				if ((ly >= 2) && (row >= 0) && (row < int(rows.size))) {
					node* n  = node_of(rows[uint32_t(row)].node);
					int   rx = 2 + 4 + rows[uint32_t(row)].depth * 16;
					if (n && n->kids.size && (lx >= rx) && (lx < rx + 12)) {
						expand_node(rows[uint32_t(row)].node, !n->expanded);
					} else {
						select_tree_node(rows[uint32_t(row)].node, true);
					}
				}
				rows.release();
				break;
			}
			case K_SLIDER: {
				ui.focus        = handle;
				bool horizontal = slider_horizontal(g);
				int  length     = horizontal ? g.w : g.h;
				int  along      = horizontal ? lx : ly;
				int  visible    = g.range_visible > 0 ? g.range_visible : 1, limit = slider_limit(g);
				int  grab       = 0;
				int  part       = bar_hit(along, g.state, visible, limit + visible, length, &grab);
				switch (part) {
				case BP_DEC:
					slider_set(handle, g, g.state - 1, true);
					break;
				case BP_INC:
					slider_set(handle, g, g.state + 1, true);
					break;
				case BP_PAGE_DEC:
					slider_set(handle, g, g.state - visible, true);
					break;
				case BP_PAGE_INC:
					slider_set(handle, g, g.state + visible, true);
					break;
				case BP_THUMB:
					drag.kind   = D_SLIDER;
					drag.handle = handle;
					drag.grab   = grab;
					post_to(event_begin_modal, handle, 0);
					break;
				default:
					break;
				}
				break;
			}
			case K_TOOLBAR:
				ui.pressed = handle;
				ui.hover   = handle;
				break;
			case K_CANVAS:
				ui.focus   = handle;
				ui.pressed = handle;
				break;
			default:
				break;
			}
		}

		void on_down(int x, int y, int button)
		{
			mouse_x = x;
			mouse_y = y;
			swallow = false;
			if (button != 1) {
				if (ui.hover) {
					gadget* h = gadget_of(ui.hover);
					if (h && (h->kind == K_CANVAS)) {
						ui.pressed = ui.hover;
					}
				}
				return;
			}
			// An open list of a combo box.
			if (ui.combo) {
				gadget* c = gadget_of(ui.combo);
				int     ax, ay;
				absolute_position(ui.combo, &ax, &ay);
				int rows = c ? (int(c->items.size) < 8 ? int(c->items.size) : 8) : 0;
				if (c && inside(x, y, ax, ay + c->h, c->w, rows * row_height(*c) + 4)) {
					int row = c->scroll + (y - ay - c->h - 2) / row_height(*c);
					int handle = ui.combo;
					ui.combo   = 0;
					if ((row >= 0) && (row < int(c->items.size))) {
						select_item(handle, row, true);
					}
					swallow = true;
					dirty();
					return;
				}
				bool on_combo = c && inside(x, y, ax, ay, c->w, c->h);
				ui.combo      = 0;
				dirty();
				if (on_combo) {
					swallow = true;
					return;
				}
			}
			// Open menus.
			if (ui.menu_window) {
				if (menu_mouse(x, y, true)) {
					swallow = true;
					return;
				}
				target t = pick(x, y);
				if ((t.part == PART_MENUBAR) && (t.window == ui.menu_window)) {
					gadget* w    = gadget_of(t.window);
					menu*   root = menu_of(w->menu);
					bool    same = ui.menu_path.size && (ui.menu_path[0] == root->kids[uint32_t(t.index)]);
					close_menus();
					if (!same) {
						open_menu_bar(t.window, t.index);
					}
				} else {
					close_menus();
				}
				swallow = true;
				return;
			}
			target t = pick(x, y);
			if (!t.window) {
				ui.focus = 0;
				dirty();
				return;
			}
			set_active_window(t.window, true);
			gadget* w = gadget_of(t.window);
			switch (t.part) {
			case PART_MINIMIZED:
				bb_restore_window(t.window);
				break;
			case PART_CLOSE:
				post_to(event_window_close, t.window, 0);
				break;
			case PART_MAX:
				if (w->maximized) {
					bb_restore_window(t.window);
				} else {
					bb_maximize_window(t.window);
				}
				break;
			case PART_MIN:
				bb_minimize_window(t.window);
				break;
			case PART_TITLE:
				if (!w->maximized) {
					drag.kind   = D_WINDOW;
					drag.handle = t.window;
					drag.ox     = x - w->x;
					drag.oy     = y - w->y;
				}
				break;
			case PART_EDGE:
				drag.kind   = D_RESIZE;
				drag.handle = t.window;
				drag.edges  = t.edges;
				drag.ox     = x;
				drag.oy     = y;
				drag.x = w->x;
				drag.y = w->y;
				drag.w = w->w;
				drag.h = w->h;
				break;
			case PART_MENUBAR:
				open_menu_bar(t.window, t.index);
				break;
			case PART_GADGET:
				press_gadget(t.handle, *gadget_of(t.handle), x, y, t.ax, t.ay);
				break;
			default:
				break;
			}
			// What was focused in another window is not any more.
			if (ui.focus && (window_of(ui.focus) != t.window)) {
				ui.focus = 0;
			}
			if (t.part != PART_GADGET) {
				ui.focus = ui.focus && (window_of(ui.focus) == t.window) ? ui.focus : 0;
			}
			dirty();
		}

		void on_up(int x, int y, int button)
		{
			mouse_x = x;
			mouse_y = y;
			if (swallow) {
				swallow = false;
				return;
			}
			if (button != 1) {
				if (ui.pressed) {
					gadget* p = gadget_of(ui.pressed);
					if (p && (p->kind == K_CANVAS)) {
						ui.pressed = 0;
					}
				}
				return;
			}
			if (drag.kind == D_SLIDER) {
				post_to(event_end_modal, drag.handle, 0);
			}
			drag = drag_state();
			int pressed = ui.pressed;
			ui.pressed = 0;
			gadget* g  = gadget_of(pressed);
			if (g) {
				if (g->kind == K_BUTTON) {
					if (ui.hover == pressed) {
						trigger_button(pressed, *g);
					}
				} else if (g->kind == K_TOOLBAR) {
					int ax, ay;
					absolute_position(pressed, &ax, &ay);
					icon_strip* strip = strip_of(g->strip);
					for (int i = 0; strip && (i < strip->count); i++) {
						int bx, by, bw, bh;
						tool_button_rect(*g, i, &bx, &by, &bw, &bh);
						int index = tool_button_index(*g, i);
						if ((index >= 0) && inside(x - ax, y - ay, bx, by, bw, bh) && (index < int(g->tool_enabled.size)) && g->tool_enabled[uint32_t(index)]) {
							post_action(pressed, index);
						}
					}
				} else if (g->kind == K_CANVAS) {
					// Where the mouse is now decides what it is over.
					target t = pick(x, y);
					ui.hover = (t.part == PART_GADGET) ? t.handle : 0;
					if (ui.hover != pressed) {
						post_to(event_mouse_leave, pressed, 0);
						if (gadget* now = gadget_of(ui.hover)) {
							if (now->kind == K_CANVAS) {
								post_to(event_mouse_enter, ui.hover, 0);
							}
						}
					}
				}
			}
			dirty();
		}

		void on_wheel(int amount)
		{
			gadget* g = gadget_of(ui.combo ? ui.combo : ui.hover);
			if (!g) {
				return;
			}
			if ((g->kind == K_TEXTAREA) && has_hbar(*g) && (SDL_GetModState() & SDL_KMOD_SHIFT)) {
				g->scroll_x -= amount * font_size(*g) * 4; // Shift turns the wheel sideways.
				clamp_scroll(*g);
				dirty();
			} else if ((g->kind == K_LISTBOX) || (g->kind == K_TREEVIEW) || (g->kind == K_TEXTAREA) || (g->kind == K_COMBOBOX)) {
				scroll_of(*g) -= amount * 3;
				if (g->kind == K_COMBOBOX) {
					int most = int(g->items.size) - 8;
					g->scroll = clampi(g->scroll, 0, most < 0 ? 0 : most);
				} else {
					clamp_scroll(*g);
				}
				dirty();
			}
		}

		bool on_key(SDL_Scancode key, SDL_Keymod mods)
		{
			if (ui.menu_window) {
				if (key == SDL_SCANCODE_ESCAPE) {
					close_menus();
					return true;
				}
				return true;
			}
			gadget* f = gadget_of(ui.focus);
			if (f && f->enabled && ((f->kind == K_TEXTFIELD) || (f->kind == K_TEXTAREA))) {
				if (key == SDL_SCANCODE_TAB && !(f->kind == K_TEXTAREA)) {
					focus_next((mods & SDL_KMOD_SHIFT) != 0);
					return true;
				}
				if (key == SDL_SCANCODE_ESCAPE) {
					int window = active_window();
					if (int cancel = default_button(window, 5)) {
						trigger_button(cancel, *gadget_of(cancel));
						return true;
					}
					return false;
				}
				if (edit_key(ui.focus, *f, key, mods)) {
					return true;
				}
				return (key == SDL_SCANCODE_LCTRL) || (key == SDL_SCANCODE_RCTRL) || false;
			}
			if (f && (f->kind == K_CANVAS)) {
				if (key == SDL_SCANCODE_TAB) {
					focus_next((mods & SDL_KMOD_SHIFT) != 0);
					return true;
				}
				return false;
			}
			int window = active_window();
			if (!window) {
				return false;
			}
			if (key == SDL_SCANCODE_TAB) {
				focus_next((mods & SDL_KMOD_SHIFT) != 0);
				return true;
			}
			if (f && f->enabled) {
				if ((f->kind == K_BUTTON) && ((key == SDL_SCANCODE_SPACE) || (key == SDL_SCANCODE_RETURN))) {
					trigger_button(ui.focus, *f);
					return true;
				}
				if (list_key(ui.focus, *f, key)) {
					return true;
				}
			}
			if ((key == SDL_SCANCODE_RETURN) || (key == SDL_SCANCODE_KP_ENTER)) {
				if (int def = default_button(window, 4)) {
					trigger_button(def, *gadget_of(def));
					return true;
				}
			}
			if (key == SDL_SCANCODE_ESCAPE) {
				if (int cancel = default_button(window, 5)) {
					trigger_button(cancel, *gadget_of(cancel));
					return true;
				}
			}
			return false;
		}

		bool on_text(const char* text)
		{
			gadget* f = gadget_of(ui.focus);
			if (!f || !f->enabled || ((f->kind != K_TEXTFIELD) && (f->kind != K_TEXTAREA)) || ui.menu_window) {
				return false;
			}
			// UTF-8 for what was typed. Blitz only knows about 8 bit characters.
			char  out[256];
			int   n = 0;
			const unsigned char* p = reinterpret_cast<const unsigned char*>(text);
			while (*p && (n < 250)) {
				int code = *p++;
				if (code >= 0xC0 && *p) {
					code = ((code & 0x1F) << 6) | (*p++ & 0x3F);
				} else if (code >= 0x80) {
					code = 0;
					while ((*p & 0xC0) == 0x80) {
						p++;
					}
				}
				if ((code >= 32 && code < 256) || (code == 9)) {
					out[n++]  = char(code);
					last_char = code;
				}
			}
			out[n] = 0;
			if (n) {
				replace_selection(ui.focus, *f, out, last_char);
			}
			return true;
		}

		void to_buffer(float ex, float ey, int* x, int* y)
		{
			int ww = 1, wh = 1;
			SDL_GetWindowSize(bb::gfx::g.window, &ww, &wh);
			*x = int(ex * float(bb::gfx::g.width) / float(ww));
			*y = int(ey * float(bb::gfx::g.height) / float(wh));
		}
	} // namespace

	void text_changed(int handle, int key)
	{
		post_action(handle, key);
	}

	// What the window tells: true if the gadgets took it.
	bool handle_event(void const* data)
	{
		if (modal_handler) {
			return modal_handler(data);
		}
		if (!gui_used) {
			return false;
		}
		SDL_Event const& e = *static_cast<SDL_Event const*>(data);
		switch (e.type) {
		case SDL_EVENT_MOUSE_MOTION: {
			int x, y;
			to_buffer(e.motion.x, e.motion.y, &x, &y);
			on_motion(x, y);
			return false;
		}
		case SDL_EVENT_MOUSE_BUTTON_DOWN: {
			int x, y;
			to_buffer(e.button.x, e.button.y, &x, &y);
			int button = (e.button.button == SDL_BUTTON_LEFT) ? 1 : ((e.button.button == SDL_BUTTON_RIGHT) ? 2 : 3);
			on_motion(x, y);
			on_down(x, y, button);
			return false;
		}
		case SDL_EVENT_MOUSE_BUTTON_UP: {
			int x, y;
			to_buffer(e.button.x, e.button.y, &x, &y);
			int button = (e.button.button == SDL_BUTTON_LEFT) ? 1 : ((e.button.button == SDL_BUTTON_RIGHT) ? 2 : 3);
			on_up(x, y, button);
			return false;
		}
		case SDL_EVENT_MOUSE_WHEEL:
			on_wheel(int(e.wheel.y));
			return false;
		case SDL_EVENT_KEY_DOWN:
			return on_key(e.key.scancode, SDL_GetModState());
		case SDL_EVENT_TEXT_INPUT:
			return on_text(e.text.text);
		default:
			return false;
		}
	}

	// Mouse and key events that the window made are for canvases, and tell where in them. False for the ones that are for
	// nothing.
	bool translate(int kind, int* x, int* y, int* source)
	{
		if (!gui_used) {
			return true;
		}
		if ((kind >= 0x201) && (kind <= 0x206)) {
			if ((kind == event_mouse_enter) || (kind == event_mouse_leave)) {
				return false; // Canvases get these when the mouse gets on or off of them.
			}
			int canvas = ui.pressed ? ui.pressed : ui.hover;
			gadget* c  = gadget_of(canvas);
			if (!c || (c->kind != K_CANVAS)) {
				return false;
			}
			int ax, ay;
			absolute_position(canvas, &ax, &ay);
			*x -= ax;
			*y -= ay;
			*source = canvas;
			return true;
		}
		if ((kind >= 0x101) && (kind <= 0x103)) {
			gadget* f = gadget_of(ui.focus);
			if (f && (f->kind == K_CANVAS)) {
				*source = ui.focus;
			}
		}
		(void)y;
		return true;
	}

	// Where the mouse is in a canvas.
	void canvas_mouse(int canvas, int* x, int* y)
	{
		int ax = 0, ay = 0;
		if (gadget_of(canvas)) {
			absolute_position(canvas, &ax, &ay);
		}
		*x -= ax;
		*y -= ay;
	}
} // namespace bb::gui

extern "C" {
int32_t bb_gui_live(void)
{
	return bb::gfx::active() ? 1 : 0;
}

int32_t bb_gui_event(const void* event)
{
	return bb::gui::handle_event(event) ? 1 : 0;
}

int32_t bb_gui_translate(int32_t kind, int32_t* x, int32_t* y, int32_t* source)
{
	int ix = *x, iy = *y, is = *source;
	bool keep = bb::gui::translate(kind, &ix, &iy, &is);
	*x      = ix;
	*y      = iy;
	*source = is;
	return keep ? 1 : 0;
}

// Used by MouseX and MouseY: the position of the mouse in a canvas, or in the window for 0.
int32_t bb_gui_mouse_in(int32_t canvas, int32_t* x, int32_t* y)
{
	int ix = *x, iy = *y;
	bb::gui::canvas_mouse(canvas, &ix, &iy);
	*x = ix;
	*y = iy;
	return 1;
}
}

extern "C" {
void bb_activate_gadget(int32_t handle)
{
	bb::gui::need_gadget(handle, "ActivateGadget");
	bb::gui::ui.focus = handle;
	bb::gui::dirty();
}
}
